/*
 * Command-button icons: glyphs from game-icons.net (CC BY 3.0, see README) lit and framed
 * in the style of WC3 buttons. The glyph paths live in gameIconPaths.ts, generated by
 * scripts/build-icons.mjs from the `icon:` names below.
 */
import { GAME_ICON_PATHS } from './gameIconPaths';

interface IconStyle {
  icon: string;
  /** Backdrop centre and edge. */
  bg: [string, string];
  /** Glyph gradient, top to bottom. */
  fg: [string, string];
  glow: string;
}

const BTN = 'replaceabletextures\\commandbuttons\\';
const PAS = 'replaceabletextures\\passivebuttons\\';

const fire = (icon: string): IconStyle => ({ icon, bg: ['#7a2a08', '#170502'], fg: ['#fff3b0', '#ff7a14'], glow: '#ff5a00' });
const item = (icon: string, tint = '#d8a850', glow = '#c08020', bg = '#3e2c12'): IconStyle => ({ icon, bg: [bg, '#0a0603'], fg: ['#fff6dc', tint], glow });

