const glyphs = new Map<string, Path2D>();
function glyph(name: string): Path2D | null {
  let p = glyphs.get(name);
  if (!p) {
    const d = GAME_ICON_PATHS[name];
    if (!d) return null;
    p = new Path2D(d);
    glyphs.set(name, p);
  }
  return p;
}

const norm = (path: string) => path.toLowerCase().replace(/\//g, '\\');

export function paintOpenIcon(path: string, g: CanvasRenderingContext2D, s: number): boolean {
  const st = STYLES[norm(path)];
  const p = st && glyph(st.icon);
  if (!st || !p) return false;
  g.save();
  const back = g.createRadialGradient(s * 0.5, s * 0.42, s * 0.05, s * 0.5, s * 0.5, s * 0.72);
  back.addColorStop(0, st.bg[0]);
  back.addColorStop(0.7, st.bg[1]);
  back.addColorStop(1, '#000');
  g.fillStyle = back;
  g.fillRect(0, 0, s, s);

  // The glyphs are drawn on a 512 box; leave a margin for the glow and frame.
  const k = (s * 0.76) / 512;
  const o = (s - 512 * k) / 2;
  g.translate(o, o);
  g.scale(k, k);
  g.shadowColor = st.glow;
  g.shadowBlur = s * 0.16;
  g.fillStyle = st.glow;
  g.globalAlpha = 0.55;
  g.fill(p);
  g.globalAlpha = 1;
  g.shadowColor = 'rgba(0,0,0,0.85)';
  g.shadowBlur = s * 0.04;
  g.shadowOffsetY = s * 0.02;
  const face = g.createLinearGradient(0, 40, 0, 470);
  face.addColorStop(0, st.fg[0]);
  face.addColorStop(1, st.fg[1]);
  g.fillStyle = face;
  g.fill(p);
  g.restore();

  // A soft top-down sheen, like the lit face of a WC3 button.
  const sheen = g.createLinearGradient(0, 0, 0, s);
  sheen.addColorStop(0, 'rgba(255,255,255,0.12)');
  sheen.addColorStop(0.45, 'rgba(255,255,255,0)');
  sheen.addColorStop(1, 'rgba(0,0,0,0.25)');
  g.fillStyle = sheen;
  g.fillRect(0, 0, s, s);
  return true;
}
